struct Config { query: String, path: String }
fn run(config: &Config) {
    println!("search {} in {}", config.query, config.path);
}
fn main() {
    let config = Config { query: String::from("bird"), path: String::from("notes.txt") };
    run(&config);
}

struct Config { query: String, path: String }
impl Config {
    fn new(args: &[String]) -> Result<Self, &'static str> {
        if args.len() != 3 { return Err("expected QUERY and PATH"); }
        Ok(Self { query: args[1].clone(), path: args[2].clone() })
    }
}
fn main() {
    let args = vec![String::from("finder")];
    match Config::new(&args) {
        Ok(c) => println!("{} {}", c.query, c.path),
        Err(message) => eprintln!("{}", message),
    }
}

use std::{fs, io};
fn run(path: &str) -> io::Result<()> {
    let text = fs::read_to_string(path)?;
    println!("{} lines", text.lines().count());
    Ok(())
}
fn main() {
    if let Err(error) = run("notes.txt") {
        eprintln!("finder failed: {}", error);
    }
}

