fn search<'a>(query: &str, text: &'a str) -> Vec<&'a str> {
    let mut found = Vec::new();
    for line in text.lines() {
        if line.contains(query) { found.push(line); }
    }
    found
}
fn main() {
    for line in search("bird", "quiet lake
bird on branch
stone path") {
        println!("{}", line);
    }
}

