#[cfg(test)]
mod tests {
    use super::insensitive;
    #[test]
    fn ignores_ascii_case() {
        assert_eq!(insensitive("BIRD", "a Bird rests
stones"), vec!["a Bird rests"]);
    }
}
fn main() {}

fn insensitive<'a>(query: &str, text: &'a str) -> Vec<&'a str> {
    let query = query.to_lowercase();
    let mut found = Vec::new();
    for line in text.lines() {
        if line.to_lowercase().contains(&query) { found.push(line); }
    }
    found
}
fn main() {
    for line in insensitive("BIRD", "a Bird rests
stones") { println!("{}", line); }
}

