fn search<'a>(query: &str, text: &'a str) -> Vec<&'a str> {
    text.lines().filter(|line| line.contains(query)).collect()
}
fn main() {
    let text = String::from("red kite
blue boat
red leaf");
    for line in search("red", &text) { println!("{}", line); }
}
